{
  "query": "how does the subscription renewal reminder work",
  "results": [
    {
      "title": "Managing auto-renewal and reminder emails",
      "url": "https://help.northbox.app/billing/auto-renew",
      "snippet": "Northbox sends a reminder 14 days before each renewal. You can change the reminder window or turn reminders off entirely under Settings > Billing > Notifications. Payment is retried up to three times if the card is declined."
    },
    {
      "title": "Why did I get a renewal email if I already cancelled?",
      "url": "https://support.northbox.app/articles/renewal-after-cancel",
      "snippet": "A cancellation takes effect at the end of the current paid period. If your reminder was already scheduled, it may still arrive; ignore it, since no charge will be made after the end date shown in your account."
    },
    {
      "title": "Northbox community thread: chatbot said my plan refreshes monthly",
      "url": "https://community.northbox.app/t/chatbot-renewal-confusion/8821",
      "snippet": "I asked the billing chatbot when my plan refreshes and it told me monthly, but my invoice shows annual. A support agent confirmed the annual date was correct and said the bot had been corrected."
    }
  ]
}

{
  "doc_type": "lease_clause_excerpt",
  "section": "7.2 Entry and Inspection",
  "text": "Landlord may enter the Premises upon twenty-four (24) hours' written notice to Tenant, or without notice in the event of an emergency, to inspect, make repairs, or show the unit to prospective tenants during the final sixty (60) days of the term. Notice may be delivered by email to the address on file or by posting on the entry door.",
  "citations": ["LKS-4B-2024 p.4", "state landlord-tenant act sec. 14(b)"]
}
